def window_sums(nums, k):
    if k <= 0:
        raise ValueError("k must be a positive integer")
    n = len(nums)
    if k > n:
        return []
    window_sum = sum(nums[:k])
    result = [window_sum]
    for i in range(k, n):
        window_sum += nums[i] - nums[i - k]
        result.append(window_sum)
    return result
